"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["30761"],{861(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.publicacoes.ato_normativo.retificacao_incompleta","status":422,"titulo":"A retifica\xe7\xe3o deve trazer o ato retificado e o motivo, ou nenhum dos dois"},"descricao":{"codigo":"uniplus.publicacoes.ato_normativo.retificacao_incompleta","requisitos":[],"oQueAconteceu":["A retifica\xe7\xe3o foi informada pela metade, ou o identificador do **ato retificado** est\xe1 vazio. Retificar um ato exige os dois campos juntos: `atoRetificadoId` e `motivoRetificacao`. Um ato que n\xe3o retifica nada deve omitir os dois.","O campo da recusa, em `errors[].field`, aponta o que falta: o `atoRetificadoId` ou o `motivoRetificacao`. Um identificador vazio \xe9 recusado mesmo quando o motivo n\xe3o foi informado.","O registro do ato confere todos os campos do pedido numa s\xf3 passada: se mais de um campo estiver errado, a resposta traz uma recusa para cada um, na ordem do corpo do pedido, em `errors`. Corrija todos e reenvie."],"comoResolver":["Se o ato retifica outro, informe o identificador do ato retificado e o motivo da retifica\xe7\xe3o. Se n\xe3o retifica, omita os dois campos."],"ondeAparece":["Registro de ato normativo, quando o pedido declara retifica\xe7\xe3o"]},"modulo":{"id":"publicacoes","nome":"Publica\xe7\xf5es","assunto":"Ato normativo"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"e5dad467d85ce0f062b88f68241ad834bc540cf0"}}')}}]);